function foodFix(fc, ev) { const mn = fc.s ? setMin(fc.s, fc.v) : fc.v.rules.minGuests, need = Math.max(mn, fc.v.site && fc.v.site.minOrder ? Math.ceil(fc.v.site.minOrder / Math.max(1, fc.pp)) : 0); return need > (+ev.guests || 0) ? `<button type="button" class="btn btn-sm" data-a="cart-guests" data-n="${need}">${L(`${need} kishiga oshirish`, `Увеличить до ${need}`, `Set to ${need} guests`)}</button>` : `<button type="button" class="btn btn-sm" data-a="cart-focus" data-id="ce-d">${L("Sanani o‘zgartirish", "Изменить дату", "Change date")}</button>`; }
function rentFix(x) { const r = x.r, b = bookedQty(r.id, S.cart.ev.date); if (x.x.mode !== "service" && x.x.qty < r.min) return `<button type="button" class="link" data-a="cart-rent-qty" data-i="${x.i}" data-n="${r.min}">${L(`${r.min} ga oshirish`, `увеличить до ${r.min}`, `set to ${r.min}`)}</button>`; if (r.stock && x.x.qty + b > r.stock && r.cat !== "joy") return `<button type="button" class="link" data-a="cart-rent-qty" data-i="${x.i}" data-n="${Math.max(1, r.stock - b)}">${L(`${Math.max(1, r.stock - b)} ga kamaytirish`, `уменьшить до ${Math.max(1, r.stock - b)}`, `set to ${Math.max(1, r.stock - b)}`)}</button>`; return `<button type="button" class="link" data-a="go" data-to="ijara" data-q='${JSON.stringify({ c: r.cat, s: r.sub })}'>${L("Boshqasini tanlash", "Выбрать другое", "Choose another")}</button>`; }
const DEF_CHECK = t => (/to‘y|osh/i.test(t) ? [["Menyuni yaqinlar bilan kelishish", "Согласовать меню с близкими", "Agree the menu with family"], ["Joyni band qilish", "Забронировать площадку", "Book the venue"], ["Mehmonlar ro‘yxati va taklifnoma (RSVP)", "Список гостей и приглашения (RSVP)", "Guest list and invitations (RSVP)"], ["Bezak, musiqa va boshlovchi", "Декор, музыка и ведущий", "Decor, music and host"], ["Transport", "Транспорт", "Transport"], ["Qoldiq to‘lovlarni tayyorlash", "Подготовить оплату остатка", "Prepare balance payments"]] : /korp|ofis/i.test(t) ? [["Mehmonlar ro‘yxati", "Список гостей", "Guest list"], ["Taqdimot va ovoz uskunasi", "Презентация и звук", "Slides and sound"], ["Hisob-faktura rekvizitlari", "Реквизиты для счёта", "Invoice details"]] : [["Mehmonlarni taklif qilish", "Пригласить гостей", "Invite guests"], ["Tort va bezak", "Торт и декор", "Cake and decor"], ["Joyni tayyorlash", "Подготовить место", "Prepare the venue"]]).map(x => L(...x));
function placeOrder() {
  const k = cartCalc(), me = cli(); if (!k || !me) return;
  const c = k.c, ev = c.ev, now = Date.now();
  let e = c.eventId ? EV(c.eventId) : null; if (e && e.clientId !== me.id) e = null;
  if (!e) { e = { id: uid("E"), clientId: me.id, title: ev.title || `${evL(ev.type)} · ${dL(ev.date)}`, type: ev.type, date: ev.date, time: ev.time, guests: ev.guests, venue: ev.address, area: ev.area, budget: Math.round(k.sub * 1.15 / 1e5) * 1e5, status: "faol", timeline: [], checklist: DEF_CHECK(ev.type).map((text, i) => ({ id: uid("ck"), text, due: dAdd(Math.max(0, daysBetween(today(), ev.date) - (6 - i))), done: false, who: "" })), guestList: [], tables: [], budgetLines: [], live: [], orders: [], bookings: [], share: null, rsvpToken: uid("rsvp"), createdAt: now }; db.events.push(e); }
  const bal = Math.max(0, walletBal(me.id)), disc = c.useWallet ? Math.min(bal, Math.round(k.sub * siteS().maxSpendPct / 100)) : 0;
  // chegirma har bir buyurtmaga summasiga qarab bo‘linadi (har vendor o‘z ulushini ko‘radi, CaterFlow qoplaydi)
  const share = tot => k.sub ? Math.round(disc * tot / k.sub / 100) * 100 : 0;
  const lines = [];
  if (k.fc) {
    const fc = k.fc, v = fc.v, oid = nextOrderId(), oset = c.food.built ? makeCustomSet("os-" + oid, v.id, c.food.built) : makeOrderSet("os-" + oid, fc.s, c.food.picks);
    const auto = !!(v.site && v.site.autoAccept && !c.food.built && (!v.site.autoMax || ev.guests <= v.site.autoMax));
    const o = { id: oid, leadId: null, customer: me.name, phone: me.phone, eventType: ev.type, date: ev.date, guests: ev.guests, budget: fc.pp, area: ev.area, venue: ev.address, notes: [c.food.note, ev.notes].filter(Boolean).join(" · "), status: auto ? "tasdiqlandi" : "vendorlarda", vendorId: auto ? v.id : null, createdAt: now, clientId: me.id, channel: "cart", eventId: e.id, token: Math.random().toString(36).slice(2, 8),
      requests: [{ vendorId: v.id, status: auto ? "javob" : "kutilmoqda", reason: "", sentAt: now, quote: auto ? { setId: oset.id, pp: fc.pp, includes: [...(oset.includes || [])], note: "Savat orqali buyurtma (avto-tasdiq)", at: now } : null, toCustomer: auto }],
      history: [{ at: now, text: `Saytda savat orqali buyurtma berildi${isMgr(me) ? " (event menejer)" : ""}` }],
      cart: { setId: oset.id, baseSetId: fc.s ? fc.s.id : null, built: !!c.food.built, pp: fc.pp, delivery: fc.fee, choices: (fc.chosen || []).map(([gr, os]) => [gr.name, os.map(x => x.name)]), time: ev.time, address: ev.address, discount: share(fc.total + fc.fee) } };
    if (auto) { o.pendingReserve = true; o.history.push({ at: now, text: `${v.name}: qoidalarga mos — avtomatik tasdiqlandi` }); }
    db.orders.push(o); e.orders.push(oid); lines.push(oid);
    notifyV(v.id, auto ? `Saytdan yangi buyurtma avtomatik tasdiqlandi: ${oid} — ${ev.type}, ${ev.guests} kishi, ${fDate(ev.date)}` : `Saytdan yangi savat buyurtmasi: ${oid} — ${ev.type}, ${ev.guests} kishi. ${siteS().confirmHours} soat ichida tasdiqlang`, { view: "vorder", param: oid });
    logS(`Saytdan savat buyurtmasi: ${oid} (${v.name})${auto ? " — avto-tasdiq" : ""}`);
    cnotifyS(me.id, auto ? L(`${v.name} buyurtmangizni darhol tasdiqladi — sana band`, `${v.name} сразу подтвердил заказ — дата забронирована`, `${v.name} confirmed instantly — the date is booked`) : L(`Buyurtma ${v.name}ga yuborildi. ${siteS().confirmHours} soat ichida tasdiqlanadi`, `Заказ отправлен в ${v.name}. Подтверждение в течение ${siteS().confirmHours} ч`, `Order sent to ${v.name}. Confirmation within ${siteS().confirmHours} hours`), { view: "c-order", param: oid });
    if (o.cart.discount) db.wallet.push({ id: uid("w"), clientId: me.id, kind: "spend", amount: -o.cart.discount, ref: oid, at: now, status: "ok", note: `${oid} buyurtmasiga chegirma` });
  }
  const byP = {}; k.rents.forEach(x => { (byP[x.r.vendorId] = byP[x.r.vendorId] || []).push(x); });
  Object.entries(byP).forEach(([pid, list]) => {
    const n = Math.max(0, ...db.rentBookings.map(b => +(/^RB-(\d+)$/.exec(b.id) || [0, 0])[1])) + 1, bid = "RB-" + n;
    const bd = share(list.reduce((a, x) => a + x.tot, 0)); if (bd) db.wallet.push({ id: uid("w"), clientId: me.id, kind: "spend", amount: -bd, ref: bid, at: now, status: "ok", note: `${bid} ijarasiga chegirma` });
    db.rentBookings.push({ id: bid, eventId: e.id, clientId: me.id, vendorId: pid, date: ev.date, status: "kutilmoqda", at: now, discount: bd, items: list.map(({ x, r }) => ({ rid: r.id, name: r.name, unit: rentUnit(r, x.mode), cat: r.cat, qty: x.qty, price: rentPrice(r, x.mode), days: r.unit === "kun" ? x.days || 1 : 1, comm: siteS().catComm[r.cat], mode: x.mode || null })), pays: [], history: [{ at: now, text: "Saytdan buyurtma" }], live: [] });
    e.bookings.push(bid); lines.push(bid);
    notifyV(pid, `Saytdan yangi ijara buyurtmasi: ${bid} — ${fDate(ev.date)}, ${list.length} ta pozitsiya`, { view: "vsite", param: "rbook" });
    logS(`Saytdan ijara buyurtmasi: ${bid} (${VV(pid).name})`);
  });
  S.cart = null; S.flash = { kind: "placed", ids: lines, eid: e.id }; commitS(); go(`tasdiq/${e.id}`);
}

