function loginDone(c) { S.session = { clientId: c.id }; if (S.cart && S.cart.eventId && (EV(S.cart.eventId) || {}).clientId !== c.id) S.cart.eventId = null; S.lang = c.lang || S.lang; c.lang = S.lang; sSaveUI(); const then = sModal && sModal.then, order = sModal && sModal.forOrder; closeM(); if (order || then === "checkout") { placeOrder(); return; } commitS(); toastS(L(`Xush kelibsiz, ${firstName(c.name)}!`, `Добро пожаловать, ${firstName(c.name)}!`, `Welcome, ${firstName(c.name)}!`)); if (then === "rfq") render(); else if (then) go(then); }
